1	import { readdirSync, readFileSync } from "node:fs";
2	import { dirname, join, relative } from "node:path";
3	import { fileURLToPath } from "node:url";
4	import { describe, expect, it } from "vitest";
5	
6	/**
7	 * The authoritative packages stay pure (CLAUDE.md, §17): no Phaser, Colyseus, DOM, timers, wall-clock time or
8	 * Math.random, so the same match can be simulated headlessly and identically on client and server.
9	 */
10	const root = join(dirname(fileURLToPath(import.meta.url)), "../..");
11	const PURE_PACKAGES = ["packages/simulation", "packages/protocol", "packages/content"];
12	
13	const FORBIDDEN_MODULES: readonly RegExp[] = [
14	  /^phaser(\/|$)/,
15	  /^colyseus(\/|$)/,
